import hashlib
import importlib.machinery
import json
import os
import platform
import subprocess
import sys
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parents[1]
SOURCE_DIR = TASK_DIR / "source"
BUILD_DIR = TASK_DIR / ".build"
STATE_FILE = BUILD_DIR / "native_state.json"
BUILD_LOG = BUILD_DIR / "native_build.log"
COMPILER = os.environ.get("CC", "cc")


def _compiler_identity() -> str:
    completed = subprocess.run(
        [COMPILER, "--version"],
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
        timeout=30,
    )
    first_line = completed.stdout.splitlines()[0] if completed.stdout else "unknown"
    return f"{COMPILER}|{completed.returncode}|{first_line}"


def _native_sources() -> list[Path]:
    paths = [
        Path(__file__),
        SOURCE_DIR / "setup.py",
        SOURCE_DIR / "pyproject.toml",
        SOURCE_DIR / "_tskitmodule.c",
    ]
    paths.extend(sorted((SOURCE_DIR / "lib").rglob("*.c")))
    paths.extend(sorted((SOURCE_DIR / "lib").rglob("*.h")))
    paths.extend(sorted((SOURCE_DIR / "lwt_interface").rglob("*.h")))
    return paths


def _fingerprint() -> str:
    digest = hashlib.sha256()
    environment = (
        platform.system(),
        platform.machine(),
        sys.implementation.name,
        platform.python_version(),
        _compiler_identity(),
    )
    digest.update("\0".join(environment).encode("utf-8"))
    digest.update(b"\0")
    for path in _native_sources():
        digest.update(path.relative_to(TASK_DIR).as_posix().encode("utf-8"))
        digest.update(b"\0")
        digest.update(path.read_bytes())
        digest.update(b"\0")
    return digest.hexdigest()


def _extension_path() -> Path | None:
    for suffix in importlib.machinery.EXTENSION_SUFFIXES:
        candidate = SOURCE_DIR / f"_tskit{suffix}"
        if candidate.is_file():
            return candidate
    return None


def build() -> Path:
    BUILD_DIR.mkdir(exist_ok=True)
    fingerprint = _fingerprint()
    extension = _extension_path()
    if extension is not None and STATE_FILE.is_file():
        try:
            state = json.loads(STATE_FILE.read_text(encoding="utf-8"))
            if state.get("fingerprint") == fingerprint:
                return extension
        except (OSError, ValueError):
            pass

    completed = subprocess.run(
        [sys.executable, "setup.py", "build_ext", "--inplace", "--force"],
        cwd=SOURCE_DIR,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
        timeout=1200,
        env={**os.environ, "CC": COMPILER},
    )
    BUILD_LOG.write_text(completed.stdout, encoding="utf-8")
